.analog-track-slot.box-shadow:
inset
        calc(
          sin(var(--analog-light-angle-track, 180deg)) *
            var(--analog-track-slot-inset-highlight-offset)
        )
        calc(
          cos(var(--analog-light-angle-track, 180deg)) *
            calc(-1 * var(--analog-track-slot-inset-highlight-offset))
        )
        var(--analog-track-slot-inset-highlight-blur)
        rgba(
          255,
          255,
          255,
          calc(var(--analog-track-slot-inset-highlight-alpha) * var(--analog-light-power, 1))
        ),
      inset
        calc(
          sin(var(--analog-light-angle-track, 180deg)) *
            calc(-1 * var(--analog-track-slot-inset-shadow-offset))
        )
        calc(
          cos(var(--analog-light-angle-track, 180deg)) *
            var(--analog-track-slot-inset-shadow-offset)
        )
        var(--analog-track-slot-inset-shadow-blur)
        rgba(
          0,
          0,
          0,
          calc(var(--analog-track-slot-inset-shadow-alpha) * var(--analog-light-power, 1))
        ),
      var(--analog-track-slot-drop-shadow)
